public class WeeklyCheckIn {static boolean valid(String s){return s!=null&&s.length()==4&&s.charAt(0)=='G'&&Character.isDigit(s.charAt(1))&&Character.isDigit(s.charAt(2))&&Character.isUpperCase(s.charAt(3));}static String check(Object[]a){int p=0,n=0,g=0,i=0;for(Object x:a){if(x==null){n++;continue;}p++;if(x.getClass().getSimpleName().contains("Group"))g++;else i++;}return p+" processed | "+n+" null skipped | "+g+" group | "+i+" individual";}public static void main(String[]x){System.out.println(valid("G45B"));}}
